152	    auto scoreUb = inUb1;
153	    auto indexUb = outUb2;
154	
155	    // CreateVecIndex只能用int32_t，GmIndex是数据块在一行数据中的起始位置，sortNumsAligned是待排序数据对32取整的结果
156	    AscendC::CreateVecIndex(indexUb, static_cast<int32_t>(GmIndex), static_cast<int32_t>(sortNumsAligned));
157	    WaitVDone();
158	
159	    uint32_t repeatTimes = sortNumsAligned / 32;
160	    auto sortDstUb = outUb1;
161	    auto sortTempUb = tmpUb;
162	
