164	    auto indexUbU32 = indexUb.ReinterpretCast<uint32_t>();
165	    AscendC::Sort<float, true>(sortDstUb, scoreUb, indexUbU32, sortTempUb, static_cast<int32_t>(repeatTimes));
166	    WaitVDone();
167	}
