21	constexpr int32_t NUM_CORES = 20;
22	constexpr int64_t UB_SORT_CAPACITY = 2048;
23	constexpr int64_t MULTI_CORE_PER_LOOP = 512;
24	constexpr int64_t ONE_LOOP_MAX = 256;
25	
26	static void computeTiling(SortKernelTiling* t, int32_t totalLength)
27	{
28	    *t = SortKernelTiling{};
29	    t->totalLength = totalLength;
30	
31	    int64_t aligned = ((int64_t)totalLength * 4 + 31) / 32 * 32 / 4;
32	    int64_t sortNum = ((aligned + 31) / 32) * 32;
33	    t->sortNum = static_cast<int32_t>(sortNum);
34	
35	    if (totalLength <= (int32_t)UB_SORT_CAPACITY) {
36	        t->tilingMode = SORT_TILING_MODE_FULLLOAD;
37	        t->coreNum = 1;
38	        t->needCoreNum = 1;
39	        return;
40	    }
41	
42	    if (totalLength <= (int32_t)(UB_SORT_CAPACITY * 2)) {
43	        t->tilingMode = SORT_TILING_MODE_SINGLECORE;
44	        t->coreNum = 1;
45	        t->needCoreNum = 1;
46	        return;
47	    }
48	
49	    t->tilingMode = SORT_TILING_MODE_MULTICORE;
50	
51	    int32_t perLoop = static_cast<int32_t>(MULTI_CORE_PER_LOOP);
52	    int32_t needCores = std::min<int32_t>(NUM_CORES, (totalLength + perLoop - 1) / perLoop);
53	    if (needCores < 2) needCores = 2;
54	
55	    t->coreNum = needCores;
56	    t->needCoreNum = needCores;
57	
58	    int32_t perCore = (totalLength + needCores - 1) / needCores;
59	    perCore = ((perCore + 31) / 32) * 32;
60	    int32_t lastCore = totalLength - perCore * (needCores - 1);
61	    if (lastCore <= 0) {
62	        perCore = totalLength / needCores;
63	        perCore = ((perCore + 31) / 32) * 32;
64	        lastCore = totalLength - perCore * (needCores - 1);
65	    }
66	
67	    t->perCoreElements = perCore;
68	    t->lastCoreElements = lastCore;
69	
70	    int32_t loopElem = std::min<int32_t>(perLoop, perCore);
71	    loopElem = ((loopElem + 31) / 32) * 32;
72	
73	    t->perCorePerLoopElements = loopElem;
74	    t->perCoreLoops = (perCore + loopElem - 1) / loopElem;
75	    t->perCoreLastLoopElements = perCore - loopElem * (t->perCoreLoops - 1);
76	
77	    t->lastCorePerLoopElements = loopElem;
78	    t->lastCoreLoops = (lastCore + loopElem - 1) / loopElem;
79	    t->lastCoreLastLoopElements = lastCore - loopElem * (t->lastCoreLoops - 1);
80	
81	    t->oneLoopMaxElements = static_cast<int32_t>(ONE_LOOP_MAX);
82	}
83	
84	std::tuple<at::Tensor, at::Tensor> kv_sort(const at::Tensor& keys, const at::Tensor& values)
85	{
86	    TORCH_CHECK(keys.dim() == 1, "keys must be 1D");
87	    TORCH_CHECK(values.dim() == 1, "values must be 1D");
88	    TORCH_CHECK(keys.size(0) == values.size(0), "keys and values must have same length");
89	    TORCH_CHECK(keys.scalar_type() == at::kInt, "keys must be int32");
90	    TORCH_CHECK(values.scalar_type() == at::kInt, "values must be int32");
91	    TORCH_CHECK(keys.is_contiguous() && values.is_contiguous(), "inputs must be contiguous");
92	
93	    int32_t totalLength = static_cast<int32_t>(keys.size(0));
94	
95	    at::Tensor sortedKeys = at::empty_like(keys);
96	    at::Tensor sortedValues = at::empty_like(values);
97	
98	    at::Tensor tilingCpu = at::empty(
99	        {static_cast<int64_t>(sizeof(SortKernelTiling))},
100	        at::device(at::kCPU).dtype(at::kByte));
101	    auto* tiling = reinterpret_cast<SortKernelTiling*>(tilingCpu.data_ptr());
102	    computeTiling(tiling, totalLength);
103	
104	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
105	
106	    int64_t wsBytes = 0;
107	    if (tiling->tilingMode == SORT_TILING_MODE_MULTICORE) {
108	        int64_t perCoreSortLen = static_cast<int64_t>(tiling->perCoreElements) * 2;
109	        int64_t oneBufFloats = static_cast<int64_t>(tiling->needCoreNum) * perCoreSortLen;
110	        wsBytes = oneBufFloats * sizeof(float) * 2 + 4096;
111	    }
112	    at::Tensor workspace = at::empty({wsBytes}, keys.options().dtype(at::kByte));
113	
114	    uint32_t blockDim = static_cast<uint32_t>(tiling->coreNum);
115	    EXEC_KERNEL_CMD(kv_sort, blockDim, keys, values, sortedKeys, sortedValues, workspace, tilingNpu);
116	
117	    return std::make_tuple(sortedKeys, sortedValues);
118	}
