#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelTopK {
public:
    __aicore__ inline KernelTopK() {}

    __aicore__ inline void Init(
        GM_ADDR x,
        GM_ADDR y,
        int64_t totalRows,
        int64_t rowLength,
        int64_t k,
        int64_t largest,
        int64_t tileLength,
        int64_t tileNum,
        int64_t tileLengthTail)
    {
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x));
        yGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y));

        this->totalRows = totalRows;
        this->rowLength = rowLength;
        this->k = k;
        this->largest = largest;
        this->tileLength = tileLength;
        this->tileNum = tileNum;
        this->tileLengthTail = tileLengthTail;

        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, k * sizeof(T));
        // Temp buffer for sort: need score-index pairs + sort temp
        // For simplicity, we use a direct selection approach in Compute
        pipe.InitBuffer(tmpQueue, 1, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        for (int64_t row = 0; row < totalRows; row++) {
            // Copy entire row from GM to UB
            LocalTensor<T> xLocal = inQueue.AllocTensor<T>();
            int64_t copyLen = rowLength;
            AscendC::DataCopyPad(xLocal, xGm[row * rowLength],
                AscendC::DataCopyExtParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(copyLen * sizeof(T)),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0)));
            inQueue.EnQue(xLocal);

            // Compute top-k
            LocalTensor<T> xIn = inQueue.DeQue<T>();
            LocalTensor<T> yLocal = outQueue.AllocTensor<T>();

            // Simple selection sort for top-k
            // For each position in output, find the max/min among remaining
            for (int64_t ki = 0; ki < k; ki++) {
                T bestVal = xIn[ki];
                int64_t bestIdx = ki;
                for (int64_t j = ki + 1; j < rowLength; j++) {
                    if (largest > 0) {
                        if (xIn[j] > bestVal) {
                            bestVal = xIn[j];
                            bestIdx = j;
                        }
                    } else {
                        if (xIn[j] < bestVal) {
                            bestVal = xIn[j];
                            bestIdx = j;
                        }
                    }
                }
                yLocal[ki] = bestVal;
                // Swap to mark as used
                if (bestIdx != ki) {
                    T tmp = xIn[ki];
                    xIn[ki] = xIn[bestIdx];
                    xIn[bestIdx] = tmp;
                }
            }

            outQueue.EnQue(yLocal);
            inQueue.FreeTensor(xIn);

            // Copy out
            LocalTensor<T> yOut = outQueue.DeQue<T>();
            AscendC::DataCopyPad(yGm[row * k], yOut,
                AscendC::DataCopyExtParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(k * sizeof(T)),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0)));
            outQueue.FreeTensor(yOut);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueue;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> tmpQueue;

    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;

    int64_t totalRows;
    int64_t rowLength;
    int64_t k;
    int64_t largest;
    int64_t tileLength;
    int64_t tileNum;
    int64_t tileLengthTail;
};

extern "C" __global__ __aicore__ void topk(
    GM_ADDR x,
    GM_ADDR y,
    int64_t totalRows,
    int64_t rowLength,
    int64_t k,
    int64_t largest,
    int64_t tileLength,
    int64_t tileNum,
    int64_t tileLengthTail)
{
    KernelTopK<float> op;
    op.Init(x, y, totalRows, rowLength, k, largest, tileLength, tileNum, tileLengthTail);
    op.Process();
}
