#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_topk.h"

namespace ascend_kernel {

at::Tensor topk(const at::Tensor& x, int64_t k, int64_t dim, int64_t largest, int64_t sorted)
{
    // Handle dim
    int64_t dimPos = dim;
    if (dimPos < 0) {
        dimPos = x.dim() + dimPos;
    }
    TORCH_CHECK(dimPos >= 0 && dimPos < x.dim(), "dim out of range");

    // Reshape to 2D: merge all dims before dim, and all dims from dim onwards
    std::vector<int64_t> shapeBefore;
    std::vector<int64_t> shapeAfter;
    for (int64_t i = 0; i < dimPos; i++) {
        shapeBefore.push_back(x.size(i));
    }
    for (int64_t i = dimPos; i < x.dim(); i++) {
        shapeAfter.push_back(x.size(i));
    }

    int64_t M = 1;
    for (auto s : shapeBefore) M *= s;
    int64_t N = 1;
    for (auto s : shapeAfter) N *= s;

    // Flatten input to 2D view
    auto x2d = x.reshape({M, N});

    // Create output tensor: shape = [M, k]
    auto y2d = at::empty({M, k}, x.options());

    // Get platform info for tiling
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Simple tiling: each core handles some rows
    int64_t totalRows = M;
    int64_t rowLength = N;

    // Tile length: how many rows per core per loop
    // For simplicity, use a fixed tile size based on UB capacity
    int64_t bufferCoefficient = (x.element_size() == 4) ? 20 : 16;
    int64_t tileLength = static_cast<int64_t>(ubSize) / bufferCoefficient / x.element_size();
    tileLength = (tileLength / 32) * 32;  // 32B align
    if (tileLength < 32) tileLength = 32;

    int64_t tileNum = (totalRows + tileLength - 1) / tileLength;
    int64_t tileLengthTail = totalRows - tileLength * (tileNum - 1);
    if (tileLengthTail <= 0) {
        tileLength = totalRows / tileNum;
        tileLength = (tileLength / 32) * 32;
        if (tileLength < 32) tileLength = 32;
        tileNum = (totalRows + tileLength - 1) / tileLength;
        tileLengthTail = totalRows - tileLength * (tileNum - 1);
    }

    int64_t blockDim = std::min(coreNum, tileNum);

    // All params must be left values for EXEC_KERNEL_CMD
    int64_t totalRowsL = totalRows;
    int64_t rowLengthL = rowLength;
    int64_t kL = k;
    int64_t largestL = largest;
    int64_t tileLengthL = tileLength;
    int64_t tileNumL = tileNum;
    int64_t tileLengthTailL = tileLengthTail;

    // Launch kernel (only float32 for now)
    EXEC_KERNEL_CMD(topk, blockDim, x2d, y2d,
        totalRowsL, rowLengthL, kL, largestL,
        tileLengthL, tileNumL, tileLengthTailL);

    // Reshape output back to original shape with k inserted at dim
    std::vector<int64_t> outputShape;
    for (int64_t i = 0; i < dimPos; i++) {
        outputShape.push_back(x.size(i));
    }
    outputShape.push_back(k);
    for (int64_t i = dimPos + 1; i < x.dim(); i++) {
        outputShape.push_back(x.size(i));
    }

    return y2d.reshape(outputShape);
}

} // namespace ascend_kernel
