                    yLocal.SetValue(ki, static_cast<bfloat16_t>(bestVal));
                }

                if (bestIdx != ki) {
                    float tmp = xFp32.GetValue(ki);
                    xFp32.SetValue(ki, bestVal);
                    xFp32.SetValue(bestIdx, tmp);
                }
            }

