{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * TopK AscendC kernel — device side.
 * Simple float32-only kernel for top-k selection.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 2;

class KernelTopK {
public:
    __aicore__ inline KernelTopK() {}

    __aicore__ inline void Init(
        GM_ADDR x,
        GM_ADDR y,
        int64_t totalRows,
        int64_t rowLength,
        int64_t k,
        int64_t largest)
    {
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x));
        yGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y));

        this->totalRows = totalRows;
        this->rowLength = rowLength;
        this->k = k;
        this->largest = largest;

        pipe.InitBuffer(inQueue, BUFFER_NUM, rowLength * sizeof(float));
        pipe.InitBuffer(outQueue, BUFFER_NUM, k * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        for (int64_t row = 0; row < totalRows; row++) {
            CopyIn(row);
            Compute(row);
            CopyOut(row);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t row)
    {
        LocalTensor<float> xLocal = inQueue.AllocTensor<float>();
        uint64_t copyLen = static_cast<uint64_t>(rowLength);
        DataCopyPad(xLocal, xGm[row * rowLength],
            DataCopyExtParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(copyLen * sizeof(float)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0)),
            DataCopyPadExtParams<float>(false, 0, 0, 0.0f));
        inQueue.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t row)
    {
        LocalTensor<float> xIn = inQueue.DeQue<float>();
        LocalTensor<float> yLocal = outQueue.AllocTensor<float>();

        // Selection sort for top-k
        for (int64_t ki = 0; ki < k; ki++) {
            float bestVal = xIn.GetValue(ki);
            int64_t bestIdx = ki;

            for (int64_t j = ki + 1; j < rowLength; j++) {
                float val = xIn.GetValue(j);
                if (largest > 0) {
                    if (val > bestVal) {
                        bestVal = val;
                        bestIdx = j;
                    }
                } else {
                    if (val < bestVal) {
                        bestVal = val;
                        bestIdx = j;
                    }
                }
            }

            yLocal.SetValue(ki, bestVal);

            if (bestIdx != ki) {
                float tmp = xIn.GetValue(ki);
                xIn.SetValue(ki, bestVal);
                xIn.SetValue(bestIdx, tmp);
            }
        }

        outQueue.EnQue(yLocal);
        inQueue.FreeTensor(xIn);
    }

    __aicore__ inline void CopyOut(int64_t row)
    {
        LocalTensor<float> yOut = outQueue.DeQue<float>();
        uint64_t copyLen = static_cast<uint64_t>(k);
        DataCopyPad(yGm[row * k], yOut,
            DataCopyExtParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(copyLen * sizeof(float)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0)));
        outQueue.FreeTensor(yOut);
    }

private:
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue;

    GlobalTensor<float> xGm;
    GlobalTensor<float> yGm;

    int64_t totalRows;
    int64_t rowLength;
    int64_t k;
    int64_t largest;
};

extern "C" __global__ __aicore__ void topk(
    GM_ADDR x, GM_ADDR y,
    int64_t totalRows, int64_t rowLength, int64_t k, int64_t largest)
{
    KernelTopK op;
    op.Init(x, y, totalRows, rowLength, k, largest);
    op.Process();
}
